import React, { useState, useRef, useEffect } from 'react';
import { Link } from 'react-router-dom';
import { PlayIcon, PauseIcon, SpeakerWaveIcon, ArrowPathIcon, ArrowDownTrayIcon, ChevronDownIcon } from '@heroicons/react/24/solid';

interface AudioControls {
  volume: number;
  speed: number;
}

interface WordTiming {
  word: string;
  start: number;
  end: number;
}

const DocumentUploadPage: React.FC = () => {
  const [file, setFile] = useState<File | null>(null);
  const [extractedText, setExtractedText] = useState<string>('');
  const [audioUrl, setAudioUrl] = useState<string>('');
  const [isGenerating, setIsGenerating] = useState(false);
  const [isPlaying, setIsPlaying] = useState(false);
  const [currentTime, setCurrentTime] = useState(0);
  const [duration, setDuration] = useState(0);
  const [wordTimings, setWordTimings] = useState<WordTiming[]>([]);
  const [highlightedWordIndex, setHighlightedWordIndex] = useState<number>(-1);

  const audioRef = useRef<HTMLAudioElement | null>(null);
  const progressBarRef = useRef<HTMLDivElement>(null);
  const [controls, setControls] = useState<AudioControls>({
    volume: 1,
    speed: 1
  });

  // Add timeUpdate handler
  const handleTimeUpdate = () => {
    if (audioRef.current) {
      const currentTime = audioRef.current.currentTime;
      setCurrentTime(currentTime);

      // Update highlighted word based on current time
      const currentWordIndex = wordTimings.findIndex(
        timing => currentTime >= timing.start && currentTime <= timing.end
      );

      if (currentWordIndex !== highlightedWordIndex) {
        setHighlightedWordIndex(currentWordIndex);

        // Scroll the highlighted word into view if needed
        const wordElement = document.getElementById(`word-${currentWordIndex}`);
        if (wordElement) {
          wordElement.scrollIntoView({ behavior: 'smooth', block: 'center' });
        }
      }
    }
  };

  // Initialize audio element
  useEffect(() => {
    if (audioUrl && !audioRef.current) {
      const audio = new Audio(audioUrl);
      audio.addEventListener('timeupdate', handleTimeUpdate);
      audio.addEventListener('loadedmetadata', () => {
        setDuration(audio.duration);
      });
      audio.addEventListener('ended', () => {
        setIsPlaying(false);
        setHighlightedWordIndex(-1);
      });
      audioRef.current = audio;
    }

    return () => {
      if (audioRef.current) {
        audioRef.current.removeEventListener('timeupdate', handleTimeUpdate);
        audioRef.current.pause();
        audioRef.current = null;
      }
    };
  }, [audioUrl, highlightedWordIndex, wordTimings]);

  // Handle file upload
  const handleFileUpload = async (event: React.ChangeEvent<HTMLInputElement>) => {
    const selectedFile = event.target.files?.[0];
    if (!selectedFile) return;

    setFile(selectedFile);
    const formData = new FormData();
    formData.append('file', selectedFile);

    try {
      const response = await fetch('http://localhost:8000/api/pdf/upload', {
        method: 'POST',
        body: formData,
      });

      if (!response.ok) throw new Error('Failed to upload file');

      const data = await response.json();
      setExtractedText(data.text);
    } catch (error) {
      console.error('Error uploading file:', error);
      alert('Error uploading file');
    }
  };

  // Format time display
  const formatTime = (time: number): string => {
    const minutes = Math.floor(time / 60);
    const seconds = Math.floor(time % 60);
    return `${minutes}:${seconds.toString().padStart(2, '0')}`;
  };

  // Handle generate speech
  const handleGenerateSpeech = async () => {
    if (!extractedText) return;

    setIsGenerating(true);
    try {
      const response = await fetch('http://localhost:8000/api/pdf/read', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          text: extractedText,
          voice_path: localStorage.getItem('voicePath') || '',
          format: 'mp3'
        }),
      });

      if (!response.ok) throw new Error('Failed to generate speech');

      const data = await response.json();
      setAudioUrl(`http://localhost:8000${data.audio_url}`);
      setWordTimings(data.word_timings);

    } catch (error) {
      console.error('Error generating speech:', error);
      alert('Error generating speech');
    } finally {
      setIsGenerating(false);
    }
  };

  // Render text with highlighting
  const renderText = () => {
    if (!extractedText) return null;

    return extractedText.split(' ').map((word, index) => (
      <span
        key={index}
        id={`word-${index}`}
        className={`inline-block mx-0.5 px-0.5 rounded transition-colors duration-200 ${
          index === highlightedWordIndex ? 'bg-yellow-300 text-gray-900' : ''
        }`}
      >
        {word}
      </span>
    ));
  };

  return (
    <div className="min-h-screen bg-gray-900 text-white py-8">
      <div className="max-w-4xl mx-auto px-4">
        <div className="mb-8">
          <Link to="/" className="text-blue-400 hover:text-blue-300">
            ← Back to Voice Recording
          </Link>
        </div>

        <div className="space-y-6">
          <div className="bg-gray-800 rounded-lg p-6">
            <h2 className="text-xl font-semibold mb-4">Upload PDF Document</h2>
            <input
              type="file"
              accept=".pdf"
              onChange={handleFileUpload}
              className="block w-full text-sm text-gray-400
                file:mr-4 file:py-2 file:px-4
                file:rounded-full file:border-0
                file:text-sm file:font-semibold
                file:bg-blue-50 file:text-blue-700
                hover:file:bg-blue-100"
            />
          </div>

          {extractedText && (
            <div className="bg-gray-800 rounded-lg p-6">
              <h2 className="text-xl font-semibold mb-4">Extracted Text</h2>
              <div className="bg-gray-900 rounded-lg p-4 max-h-60 overflow-y-auto text-gray-300 leading-relaxed">
                {renderText()}
              </div>

              <button
                onClick={handleGenerateSpeech}
                disabled={isGenerating}
                className="mt-4 bg-blue-600 hover:bg-blue-700 text-white px-6 py-2 rounded-lg
                  disabled:bg-gray-600 disabled:cursor-not-allowed transition-colors duration-200"
              >
                {isGenerating ? (
                  <>
                    <ArrowPathIcon className="inline w-5 h-5 mr-2 animate-spin" />
                    Generating Speech...
                  </>
                ) : (
                  'Generate Speech'
                )}
              </button>
            </div>
          )}

          {/* ... rest of your existing audio player UI code ... */}
        </div>
      </div>
    </div>
  );
};

export default DocumentUploadPage;
